const knex = require('../knexfile');
const { buildSubgraphSchema } = require('@apollo/subgraph');
const { GraphQLError } = require('graphql');
const gql = require('graphql-tag');

const typeDefs = gql`
  extend schema @link(url: "https://specs.apollo.dev/federation/v2.0", import: ["@key"])

  type EmployeeSalaryRecord @key(fields: "employeeId") {
    employeeId: ID!
    baseSalary: Float!
    equityUnits: Int!
    bonusTargetPct: Float!
  }
`;

const resolvers = {
  EmployeeSalaryRecord: {
    __resolveReference: async ({ employeeId }, context) => {
      if (!context.requester) {
        throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
      }
      const isSelf = context.requester.employeeId === employeeId;
      const isHRLead = context.requester.permissions?.includes('VIEW_COMPENSATION');
      if (!isSelf && !isHRLead) {
        throw new GraphQLError('Forbidden: unauthorized access to salary data', { extensions: { code: 'FORBIDDEN' } });
      }
      const record = await knex('employee_compensation')
        .where({ employee_id: employeeId })
        .first();
      return record ? {
        employeeId: record.employee_id,
        baseSalary: record.base_salary,
        equityUnits: record.equity_units,
        bonusTargetPct: record.bonus_target_pct,
      } : null;
    }
  }
};
